#!/bin/bash
# Generated by gen.py from fabric.py: rail2, rail leaf, AS 65202, pure L3.
set -euo pipefail
# Front-panel ports appear once syncd is up; then let the switch settle.
until ip link show Ethernet0 >/dev/null 2>&1; do sleep 1; done
until ip link show Ethernet4 >/dev/null 2>&1; do sleep 1; done
until ip link show Ethernet8 >/dev/null 2>&1; do sleep 1; done
until ip link show Ethernet12 >/dev/null 2>&1; do sleep 1; done
sleep 5
sysctl -qw net.ipv4.fib_multipath_hash_policy=1   # ECMP on the L4 hash, as on hardware
config loopback add Loopback0
config interface ip add Loopback0 10.10.1.2/32
config interface ip add Ethernet8 10.11.1.3/31
config interface startup Ethernet8
config interface ip add Ethernet12 10.11.2.3/31
config interface startup Ethernet12
config interface ip add Ethernet0 10.12.2.0/31
config interface startup Ethernet0
config interface ip add Ethernet4 10.12.2.2/31
config interface startup Ethernet4
# FRR binds an L3 VNI only to a VRF the kernel already has.
# docker-sonic-vs leaves bgpd stopped and has no bfdd program (it is
# frr_mgmt_framework-only), so start bgpd and run bfdd directly.
supervisorctl status bgpd | grep -q RUNNING || supervisorctl start bgpd
pgrep -x bfdd >/dev/null || /usr/lib/frr/bfdd -d -A 127.0.0.1
until vtysh -c 'show bfd peers' >/dev/null 2>&1; do sleep 1; done
vtysh -f /configs/frr.conf
touch /tmp/al-ready
